namespace sv_bf33e8f6f01248788cbdc004f9af0b1a.Services;

public record TaskItem(int Id, string Title, string Assignee, string Priority, DateTime DueDate, string Status);

public interface ITaskService
{
    Task<List<TaskItem>> GetAllTasksAsync();
    Task<TaskItem> CreateTaskAsync(string title, string assignee, string priority, DateTime dueDate);
    Task UpdateTaskStatusAsync(int taskId, string newStatus);
}

@using sv_bf33e8f6f01248788cbdc004f9af0b1a.Services

<div class="card mb-2">
    <div class="card-body p-2">
        <h6 class="card-title mb-1">@Task.Title</h6>
        <div class="d-flex align-items-center mb-1">
            <small class="text-muted me-2">@Task.Assignee</small>
            <span class="badge @PriorityClass">@Task.Priority</span>
            <small class="text-muted ms-auto">@Task.DueDate.ToString("MMM dd")</small>
        </div>
        <div class="d-flex gap-1">
            @if (CanMoveLeft)
            {
                <button class="btn btn-sm btn-outline-secondary" @onclick="OnMoveLeft">&larr; Move Left</button>
            }
            @if (CanMoveRight)
            {
                <button class="btn btn-sm btn-outline-secondary" @onclick="OnMoveRight">Move Right &rarr;</button>
            }
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public TaskItem Task { get; set; } = default!;
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback OnMoveLeft { get; set; }
    [Parameter] public EventCallback OnMoveRight { get; set; }

    private string PriorityClass => Task.Priority switch
    {
        "High" => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low" => "bg-success",
        _ => "bg-secondary"
    };
}

@using sv_bf33e8f6f01248788cbdc004f9af0b1a.Services
@using static BoardAddTaskForm

<div class="board-column d-flex flex-column">
    <div class="card">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h5 class="mb-0">@ColumnName</h5>
            <span class="badge bg-secondary">@Tasks.Count</span>
        </div>
        <div class="card-body p-2" style="min-height: 200px; overflow-y: auto;">
            @foreach (var task in Tasks)
            {
                <BoardTaskCard Task="task"
                               CanMoveLeft="CanMoveLeft"
                               CanMoveRight="CanMoveRight"
                               OnMoveLeft="() => OnMoveLeft.InvokeAsync(task.Id)"
                               OnMoveRight="() => OnMoveRight.InvokeAsync(task.Id)" />
            }

            @if (showAddForm)
            {
                <BoardAddTaskForm OnSave="HandleAddTask" OnCancel="() => showAddForm = false" />
            }
        </div>
        <div class="card-footer p-2">
            <button class="btn btn-sm btn-outline-primary w-100" @onclick="() => showAddForm = true">
                + Add Task
            </button>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string ColumnName { get; set; } = "";
    [Parameter] public List<TaskItem> Tasks { get; set; } = [];
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback<int> OnMoveLeft { get; set; }
    [Parameter] public EventCallback<int> OnMoveRight { get; set; }
    [Parameter] public EventCallback<NewTaskRequest> OnAddTask { get; set; }

    private bool showAddForm;

    private async Task HandleAddTask(NewTaskRequest request)
    {
        await OnAddTask.InvokeAsync(request);
        showAddForm = false;
    }
}

@page "/board"
@using sv_bf33e8f6f01248788cbdc004f9af0b1a.Services
@using sv_bf33e8f6f01248788cbdc004f9af0b1a.Components.Pages.Board
@using static BoardAddTaskForm
@inject ITaskService TaskService
@rendermode InteractiveServer

<PageTitle>Kanban Board</PageTitle>

<h3 class="mb-3">Kanban Board</h3>

@if (loading)
{
    <div class="d-flex justify-content-center p-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @errorMessage
        <button class="btn btn-sm btn-outline-danger ms-2" @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardStatsBar Total="@allTasks.Count"
                   TodoCount="@TodoTasks.Count"
                   InProgressCount="@InProgressTasks.Count"
                   DoneCount="@DoneTasks.Count"
                   OverdueCount="@OverdueCount" />

    <BoardSearchBar @bind-SearchText="searchText" />

    <div class="d-flex gap-3 align-items-start board-columns">
        <BoardColumn ColumnName="To Do"
                     Tasks="TodoTasks"
                     CanMoveLeft="false"
                     CanMoveRight="true"
                     OnMoveRight="id => MoveTask(id, \"In Progress\")"
                     OnAddTask="request => AddTask(request, \"To Do\")" />

        <BoardColumn ColumnName="In Progress"
                     Tasks="InProgressTasks"
                     CanMoveLeft="true"
                     CanMoveRight="true"
                     OnMoveLeft="id => MoveTask(id, \"To Do\")"
                     OnMoveRight="id => MoveTask(id, \"Done\")"
                     OnAddTask="request => AddTask(request, \"In Progress\")" />

        <BoardColumn ColumnName="Done"
                     Tasks="DoneTasks"
                     CanMoveLeft="true"
                     CanMoveRight="false"
                     OnMoveLeft="id => MoveTask(id, \"In Progress\")"
                     OnAddTask="request => AddTask(request, \"Done\")" />
    </div>
}

@code {
    private List<TaskItem> allTasks = [];
    private string searchText = "";
    private bool loading = true;
    private string? errorMessage;

    private IReadOnlyList<TaskItem> FilteredTasks =>
        string.IsNullOrWhiteSpace(searchText)
            ? allTasks
            : allTasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();

    private List<TaskItem> TodoTasks => FilteredTasks.Where(t => t.Status == "To Do").ToList();
    private List<TaskItem> InProgressTasks => FilteredTasks.Where(t => t.Status == "In Progress").ToList();
    private List<TaskItem> DoneTasks => FilteredTasks.Where(t => t.Status == "Done").ToList();
    private int OverdueCount => allTasks.Count(t => t.DueDate < DateTime.Today);

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        try
        {
            loading = true;
            errorMessage = null;
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            loading = false;
        }
    }

    private async Task MoveTask(int taskId, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = allTasks.FirstOrDefault(t => t.Id == taskId);
            if (task is not null)
            {
                allTasks[allTasks.IndexOf(task)] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
    }

    private async Task AddTask(NewTaskRequest request, string status)
    {
        try
        {
            var created = await TaskService.CreateTaskAsync(request.Title, request.Assignee, request.Priority, request.DueDate);
            allTasks.Add(created with { Status = status });
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
    }
}

