+                               OnMoveLeft="() => OnMoveLeft.InvokeAsync(task.Id)"
+                               OnMoveRight="() => OnMoveRight.InvokeAsync(task.Id)" />
+            }
+
+            @if (showAddForm)
+            {
+                <BoardAddTaskForm OnSave="HandleAddTask" OnCancel="() => showAddForm = false" />
+            }
+        </div>
+        <div class="card-footer p-2">
+            <button class="btn btn-sm btn-outline-primary w-100" @onclick="() => showAddForm = true">
+                + Add Task
+            </button>
+        </div>
+    </div>
+</div>
+
+@code {
+    [Parameter, EditorRequired] public string ColumnName { get; set; } = "";
+    [Parameter] public List<TaskItem> Tasks { get; set; } = [];
+    [Parameter] public bool CanMoveLeft { get; set; }
+    [Parameter] public bool CanMoveRight { get; set; }
+    [Parameter] public EventCallback<int> OnMoveLeft { get; set; }
+    [Parameter] public EventCallback<int> OnMoveRight { get; set; }
+    [Parameter] public EventCallback<NewTaskRequest> OnAddTask { get; set; }
+
+    private bool showAddForm;
+
+    private async Task HandleAddTask(NewTaskRequest request)
+    {
+        await OnAddTask.InvokeAsync(request);
+        showAddForm = false;
+    }
+}
+

